"use client"

import { useState } from "react"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Combobox,
  ComboboxContent,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  ComboboxTrigger,
} from "@/components/ui/combobox"

const statuses = ["Present", "Late", "Absent", "No tap recorded yet"]

export default function PopupLab() {
  const [status, setStatus] = useState("all")
  const [value, setValue] = useState<string | null>(null)

  return (
    <div className="flex flex-col gap-4 p-6">
      <div className="w-64">
        <Select value={status} onValueChange={setStatus}>
          <SelectTrigger aria-label="Filter by attendance status" className="w-full">
            <SelectValue>
              {status === "all" ? "All statuses" : statuses.find((s) => s.toLowerCase() === status) ?? status}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All statuses</SelectItem>
            {statuses.map((item) => (
              <SelectItem key={item} value={item.toLowerCase()}>
                {item}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="w-64">
        <Combobox
          items={statuses.map((item) => ({ value: item.toLowerCase(), label: item }))}
          value={value}
          onValueChange={(item) => setValue(item?.value ?? null)}
        >
          <ComboboxInput placeholder="Search status" />
          <ComboboxTrigger />
          <ComboboxContent>
            <ComboboxList>
              {statuses.map((item) => (
                <ComboboxItem key={item} value={{ value: item.toLowerCase(), label: item }}>
                  {item}
                </ComboboxItem>
              ))}
            </ComboboxList>
          </ComboboxContent>
        </Combobox>
      </div>

      <div className="w-64">
        <Combobox
          defaultOpen
          items={statuses.map((item) => ({ value: item.toLowerCase(), label: item }))}
          value={null}
          onValueChange={() => {}}
        >
          <ComboboxInput placeholder="Search status" />
          <ComboboxContent>
            <ComboboxList>
              {statuses.map((item) => (
                <ComboboxItem key={item} value={{ value: item.toLowerCase(), label: item }}>
                  {item}
                </ComboboxItem>
              ))}
            </ComboboxList>
          </ComboboxContent>
        </Combobox>
      </div>

      <div className="flex flex-col gap-2">
        {Array.from({ length: 40 }).map((_, index) => (
          <div key={index} className="h-20 rounded border">
            row {index}
          </div>
        ))}
      </div>
    </div>
  )
}
